const websites = [
  { name: "Google", url: "https://www.google.com" },
  { name: "Testing", url: "https://testingn8nhello.com" },
  { name: "Portfolio", url: "https://portfolio-zeta-sandy-42.vercel.app/" },
  { name: "Test Redirect (3xx)", url: "https://httpbin.org/status/301" },
  { name: "Test Client Error (4xx)", url: "https://httpbin.org/status/404" },
  { name: "Test Server Error (5xx)", url: "https://httpbin.org/status/503" }
];

return websites.map(site => ({ json: site }));

const item = $input.item;

return {
  json: {
    ...item.json,
    requestStartedAt: Date.now()
  }
};

const response = $input.item.json;
const original = $('Start Timer').item.json;

const responseTimeMs = Date.now() - original.requestStartedAt;

let performanceStatus;
if (responseTimeMs < 500) {
  performanceStatus = "Fast";
} else if (responseTimeMs < 1000) {
  performanceStatus = "Normal";
} else if (responseTimeMs <= 3000) {
  performanceStatus = "Slow";
} else {
  performanceStatus = "Very Slow";
}

// drop the (large) response body, it is not needed downstream
const { data, ...rest } = response;

return {
  json: {
    ...rest,
    name: original.name,
    url: original.url,
    responseTimeMs,
    performanceStatus
  }
};

const error = $input.item.json;
const original = $('Start Timer').item.json;

return {
  json: {
    ...error,
    name: original.name,
    url: original.url,
    responseTimeMs: Date.now() - original.requestStartedAt
  }
};

// join point for the success path and the error path, drops the big response body
const { data, ...rest } = $input.item.json;
return { json: rest };

// ===== Status change detection (uses monitor_state data table) =====
const cur = $('Prepare Check').item.json;   // current check result
const prev = $input.item.json || {};        // row from monitor_state (empty on first check)

const hasPrev = prev.lastState !== undefined && prev.lastState !== null && prev.lastState !== '';
const prevState = hasPrev ? prev.lastState : null;

// ---- current state
const code = Number(cur.statusCode);
const hasCode = cur.statusCode !== undefined && cur.statusCode !== null &&
                cur.statusCode !== '' && !Number.isNaN(code);

let state;
if (!hasCode) state = 'UNREACHABLE';
else if (code >= 200 && code < 300) state = 'UP';
else if (code >= 300 && code < 400) state = 'REDIRECT';
else if (code >= 400 && code < 500) state = 'HTTP_ERROR';
else if (code >= 500 && code < 600) state = 'SERVER_ERROR';
else state = 'UNKNOWN';

// 2xx and 3xx count as uptime
const available = state === 'UP' || state === 'REDIRECT';
const prevAvailable = prevState === null ? null : (prevState === 'UP' || prevState === 'REDIRECT');

const nowMs = Date.now();
const nowISO = new Date(nowMs).toISOString();

// ---- change detection
let statusChanged = false;
let alertType = 'NONE';
if (prevState === null) {
  // first ever check: silent if healthy, alert if not
  if (state !== 'UP') { statusChanged = true; alertType = 'INITIAL_PROBLEM'; }
} else if (state !== prevState) {
  statusChanged = true;
  if (available && !prevAvailable) alertType = 'RECOVERED';
  else if (!available && prevAvailable) alertType = 'WENT_DOWN';
  else alertType = 'STATUS_CHANGED';
}

// ---- counters
const totalChecks = (Number(prev.totalChecks) || 0) + 1;
const upChecks = (Number(prev.upChecks) || 0) + (available ? 1 : 0);
let incidents = Number(prev.incidents) || 0;
if (!available && (prevState === null || prevAvailable)) incidents += 1;

// ---- lastChangeAt = last time the site went down or came back (availability flip)
const prevChange = prev.lastChangeAt ? new Date(prev.lastChangeAt) : null;
const prevChangeValid = prevChange && !Number.isNaN(prevChange.getTime());
const flipped = prevState === null || available !== prevAvailable;
const lastChangeAt = flipped || !prevChangeValid ? nowISO : prevChange.toISOString();

// ---- downtime (only on recovery)
let downtimeMs = null;
if (available && prevState !== null && !prevAvailable && prevChangeValid) {
  downtimeMs = nowMs - prevChange.getTime();
}
const fmtDur = (t) => {
  if (t === null || t === undefined) return '';
  const sec = Math.round(t / 1000);
  const d = Math.floor(sec / 86400), h = Math.floor((sec % 86400) / 3600);
  const m = Math.floor((sec % 3600) / 60), r = sec % 60;
  return [d && d + 'd', h && h + 'h', m && m + 'm', (r || (!d && !h && !m)) && r + 's']
    .filter(Boolean).join(' ');
};

return {
  json: {
    ...cur,
    state,
    available,
    previousState: prevState,
    statusChanged,
    alertType,
    downtimeMs,
    downtimeText: fmtDur(downtimeMs),
    totalChecks,
    upChecks,
    incidents,
    uptimePercent: Math.round((upChecks / totalChecks) * 10000) / 100,
    lastChangeAt,
    checkedAtISO: nowISO
  }
};

// ===== Daily uptime report built from the two data tables =====
const monitors = $('Get Monitor State').all().map(i => i.json).filter(r => r && r.url);
const history = $('Get Check History').all().map(i => i.json).filter(r => r && r.url);
const now = Date.now();
const DAY = 86400000;

const esc = (v) => String(v ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const icon = { UP: '🟢', REDIRECT: '🟡', HTTP_ERROR: '🟠', SERVER_ERROR: '🔴', UNREACHABLE: '🔴', UNKNOWN: '⚪' };
const pct = (a, b) => (b ? Math.round((a / b) * 10000) / 100 : null);
const show = (v, suffix = '') => (v === null || v === undefined ? 'n/a' : v + suffix);
const isUp = (s) => s === 'UP' || s === 'REDIRECT';

if (monitors.length === 0) {
  return [{ json: {
    subject: '📊 Daily Uptime Report – no data yet',
    html: '<h2>📊 Daily Uptime Report</h2><p>No monitoring data found in the <strong>monitor_state</strong> table yet. Make sure the monitoring workflow is active.</p>'
  } }];
}

const rows = monitors.map(m => {
  const h24 = history.filter(h => h.url === m.url && now - new Date(h.checkedAt).getTime() <= DAY);
  const ms = h24.map(h => Number(h.responseTimeMs)).filter(v => Number.isFinite(v));
  return {
    name: m.name,
    url: m.url,
    state: m.lastState,
    uptimeAll: pct(Number(m.upChecks) || 0, Number(m.totalChecks) || 0),
    uptime24h: pct(h24.filter(h => isUp(h.state)).length, h24.length),
    checks24h: h24.length,
    avgMs: ms.length ? Math.round(ms.reduce((a, b) => a + b, 0) / ms.length) : null,
    maxMs: ms.length ? Math.max(...ms) : null,
    incidents: Number(m.incidents) || 0,
    totalChecks: Number(m.totalChecks) || 0,
    lastChangeAt: m.lastChangeAt
  };
});

const down = rows.filter(r => !isUp(r.state)).length;
const ist = (iso) => {
  const d = iso ? new Date(iso) : null;
  return d && !Number.isNaN(d.getTime())
    ? d.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' })
    : 'n/a';
};

const th = 'style="padding:8px;border:1px solid #ddd;background:#f3f4f6;text-align:left;"';
const td = 'style="padding:8px;border:1px solid #ddd;"';

const body = rows.map(r => `<tr>
  <td ${td}>${icon[r.state] || '⚪'} <strong>${esc(r.name)}</strong><br><small>${esc(r.url)}</small></td>
  <td ${td}>${esc(r.state)}</td>
  <td ${td}>${show(r.uptime24h, '%')}<br><small>${r.checks24h} checks</small></td>
  <td ${td}>${show(r.uptimeAll, '%')}<br><small>${r.totalChecks} checks</small></td>
  <td ${td}>${show(r.avgMs, ' ms')}<br><small>max ${show(r.maxMs, ' ms')}</small></td>
  <td ${td}>${r.incidents}</td>
  <td ${td}>${esc(ist(r.lastChangeAt))}</td>
</tr>`).join('');

const html = `<h2>📊 Daily Uptime Report</h2>
<p><strong>${rows.length}</strong> websites monitored, <strong>${down}</strong> currently having problems.</p>
<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;">
<tr><th ${th}>Website</th><th ${th}>Current state</th><th ${th}>Uptime (24h)</th><th ${th}>Uptime (all-time)</th><th ${th}>Avg response (24h)</th><th ${th}>Incidents</th><th ${th}>Last up/down change</th></tr>
${body}
</table>
<p><small>Uptime counts 2xx and 3xx responses as available.</small></p>
<p>Regards,<br><strong>Website Monitoring System</strong></p>`;

return [{ json: {
  subject: `📊 Daily Uptime Report – ${rows.length} sites, ${down} with problems`,
  html,
  sites: rows
} }];
